-- Restore Loyola public website snapshot only.
-- Import into the main website database after schema import.
-- This overwrites site_database content/draft_content and keeps users/admin accounts intact.

SET @loyola_public_site_snapshot = CONVERT( USING utf8mb4);

INSERT INTO site_database (
  id,
  content,
  content_version,
  published_at,
  draft_content,
  draft_content_version,
  draft_updated_at
)
VALUES (
  'main',
  @loyola_public_site_snapshot,
  1780058277197,
  '2026-05-29T12:37:57.197Z',
  @loyola_public_site_snapshot,
  1780058277197,
  '2026-05-29T12:37:57.197Z'
)
ON DUPLICATE KEY UPDATE
  content = VALUES(content),
  content_version = VALUES(content_version),
  published_at = VALUES(published_at),
  draft_content = VALUES(draft_content),
  draft_content_version = VALUES(draft_content_version),
  draft_updated_at = VALUES(draft_updated_at);
